 await ctx.addInitScript(({fault,fallback,bothVisible})=>{
  window.qa={fault,count:0,requestSuccess:0,deleteFail:false,bitmapHold:false,csp:[],previews:[]};
  document.addEventListener('securitypolicyviolation',event=>qa.csp.push(event.violatedDirective));
  const preview=URL.createObjectURL.bind(URL);URL.createObjectURL=blob=>{qa.previews.push({type:blob.type,size:blob.size});return preview(blob);};
  if(bothVisible)Object.defineProperty(document,'hidden',{configurable:true,get:()=>false});
  if(fallback)Object.defineProperty(navigator,'locks',{configurable:true,get:()=>undefined});
  if(fault==='locks-denied')Object.defineProperty(navigator,'locks',{configurable:true,get:()=>({request:()=>Promise.reject(new DOMException('Synthetic denied lock','SecurityError'))})});
  if(fault==='strict-unavailable'){const transaction=IDBDatabase.prototype.transaction;IDBDatabase.prototype.transaction=function(...args){if(args.length>2)throw new TypeError('Synthetic unsupported durability option');return transaction.apply(this,args);};}
  if(fault==='unavailable')Object.defineProperty(window,'indexedDB',{configurable:true,get:()=>undefined});
  if(typeof IDBObjectStore!=='undefined'){
   const put=IDBObjectStore.prototype.put,del=IDBObjectStore.prototype.delete;
   IDBObjectStore.prototype.put=function(value,...args){if(this.name==='originals'){qa.count++;if(qa.fault==='quota'&&qa.count>=2)throw new DOMException('Synthetic quota','QuotaExceededError');const r=put.call(this,value,...args);if(qa.fault==='abort'&&qa.count===1)r.addEventListener('success',()=>{qa.requestSuccess++;this.transaction.abort();});return r;}return put.call(this,value,...args);};
   IDBObjectStore.prototype.delete=function(...args){if(this.name==='originals'&&qa.deleteFail){qa.deleteFail=false;throw new DOMException('Synthetic cleanup failure','UnknownError');}return del.apply(this,args);};
  }
  const bitmap=window.createImageBitmap?.bind(window);if(bitmap)window.createImageBitmap=async(...args)=>{if(qa.bitmapHold)await new Promise(resolve=>{qa.releaseBitmap=resolve;});return bitmap(...args);};
 },{fault,fallback,bothVisible});
