 catch(error){failures++;results.push({name,pass:false,error:String(error).split('\n')[0]});console.error('FAIL '+name+': '+String(error).split('\n')[0]);console.error(error.stack);console.log('DEBUG '+await p.evaluate(()=>document.body.innerText.slice(-1000)).catch(()=>'<closed>'));await p.screenshot({path:root+'/failure-'+failures+'.png',fullPage:true}).catch(()=>{});}
